Lemma QuantumGateTeleportation_correct_goal_2 :
  forall
    (starting_qstate : quantum_state)
    (end_state : state)
    (actions : list action)
    (s'' : state)
    (ln1 ln2 lnX : list fin)
    (q_state0 : quantum_state)
    (la0 : list action)
    (lp1 lp2 lpX : list participant)
    (e1 : @length fin ln2 = 2)
    (n1 : @NoDup fin ln2)
    (f1 : @Forall fin (fun i : fin => i < @length (qubit_reference * (participant * fin)) (elems qubit_reference (participant * fin) (` (@projT1 {qm : finite_map qubit_reference (participant * fin) | quantum_map_wf qm} (fun qm : {qm : finite_map qubit_reference (participant * fin) | quantum_map_wf qm} => {q : state_vector (@length (qubit_reference * (participant * fin)) (elems qubit_reference (participant * fin) (` qm))) | @state_vector_wf (@length (qubit_reference * (participant * fin)) (elems qubit_reference (participant * fin) (` qm))) q}) q_state0)))) ln2)
    (e0 : @length fin ln1 = 1)
    (n0 : @NoDup fin ln1)
    (f0 : @Forall fin (fun i : fin => i < @length (qubit_reference * (participant * fin)) (elems qubit_reference (participant * fin) (` (@projT1 {qm : finite_map qubit_reference (participant * fin) | quantum_map_wf qm} (fun qm : {qm : finite_map qubit_reference (participant * fin) | quantum_map_wf qm} => {q : state_vector (@length (qubit_reference * (participant * fin)) (elems qubit_reference (participant * fin) (` qm))) | @state_vector_wf (@length (qubit_reference * (participant * fin)) (elems qubit_reference (participant * fin) (` qm))) q}) q_state0)))) ln1)
