    (e : @length fin lnX = 1)
    (n : @NoDup fin lnX)
    (f : @Forall fin (fun i : fin => i < @length (qubit_reference * (participant * fin)) (elems qubit_reference (participant * fin) (` (@projT1 {qm : finite_map qubit_reference (participant * fin) | quantum_map_wf qm} (fun qm : {qm : finite_map qubit_reference (participant * fin) | quantum_map_wf qm} => {q : state_vector (@length (qubit_reference * (participant * fin)) (elems qubit_reference (participant * fin) (` qm))) | @state_vector_wf (@length (qubit_reference * (participant * fin)) (elems qubit_reference (participant * fin) (` qm))) q}) q_state0)))) lnX)
    (v'0 v'2 : qubit_reference)
    (Hqmwf :
        quantum_map_wf
        (@insert qubit_reference qr_dec (participant * fin)
        (@insert qubit_reference qr_dec (participant * fin) (` (@projT1 {qm : finite_map qubit_reference (participant * fin) | quantum_map_wf qm} (fun qm : {qm : finite_map qubit_reference (participant * fin) | quantum_map_wf qm} => {q : state_vector (@length (qubit_reference * (participant * fin)) (elems qubit_reference (participant * fin) (` qm))) | @state_vector_wf (@length (qubit_reference * (participant * fin)) (elems qubit_reference (participant * fin) (` qm))) q}) starting_qstate)) v'0
        (Source, @length (qubit_reference * (participant * fin)) (elems qubit_reference (participant * fin) (` (@projT1 {qm : finite_map qubit_reference (participant * fin) | quantum_map_wf qm} (fun qm : {qm : finite_map qubit_reference (participant * fin) | quantum_map_wf qm} => {q : state_vector (@length (qubit_reference * (participant * fin)) (elems qubit_reference (participant * fin) (` qm))) | @state_vector_wf (@length (qubit_reference * (participant * fin)) (elems qubit_reference (participant * fin) (` qm))) q}) starting_qstate))))) v'2
        (Source,
