Theorem QuantumGateTeleportation_correct:
forall starting_qstate end_state qA qB actions pi,
multistep (starting_qstate, gate_teleportation qA qB) actions end_state pi ->
finished (snd end_state) ->
length ((proj1_sig  (projT1 starting_qstate)).(elems _ _)) = 2 ->
(proj1_sig  (projT1 starting_qstate)) qA = Some (Env, 0) ->
(proj1_sig  (projT1 starting_qstate)) qB = Some (Env, 1) ->
@ray_equiv _ 4 (proj1_sig (projT2 (fst end_state))) (cz × (proj1_sig (projT2 starting_qstate))).
Proof.
  unfold gate_teleportation; simpl; intros.
  simpl in *.
  eapply multistep_partial_sort in H; cleanup; simpl in *; cleanup.
  unfold equivalent_states in *; cleanup.
  eapply finished_unfoldM_r in H4; eauto.
  clear H0.
  pose proof (partial_sort_pairwise_sorted should_swap actions should_swap_true_swap) as Hsort.

  eapply Source_correct in H; eauto. 
  cleanup_light; simpl in *.

  eapply multistep_partial_sort_no_newq in H0; cleanup_light; simpl in *; cleanup_light; [|intuition eauto].
  2: {
    unfold no_newq_session.
    Transparent insert.
    simpl; intros; repeat case_analysis; cleanup_light.
    unfold P_A; simpl; eauto.
    unfold P_B; simpl; eauto.
    unfold P_E; simpl; eauto.
    simpl; eauto.
    all: try (unfold P_A, P_B, P_E in *; simpl in *; eauto).
    Opaque insert.
  }

  unfold equivalent_states in *; cleanup_light.
  eapply finished_unfoldM_r in H17; eauto.
  clear H4.
  pose proof (partial_sort_pairwise_sorted should_swap_no_newq la0 should_swap_no_newq_true_swap) as Hsort2.
  pose proof should_swap_no_newq_facts as Hswap; logic_clean.
  unfold P_A, P_B, P_S, P_E in *.

  process_step;
  rewrite <- H29 in Hsort2; clear H29.
  simpl in *; cleanup_light; simpl in *.

  process_step.
  {
    process_step.
    process_step.
